from typing import List

class Solution:
    def maxScore(self, grid: List[List[int]]) -> int:
        dp = {0: 0}
        for row in grid:
            new_dp = dict(dp)
            for mask, score in dp.items():
                for v in set(row):
                    bit = 1 << v
                    if mask & bit:
                        continue
                    nm = mask | bit
                    ns = score + v
                    if new_dp.get(nm, -1) < ns:
                        new_dp[nm] = ns
            dp = new_dp
        return max(s for m, s in dp.items() if m != 0)
